def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find the full row or column that acts as the boundary.
    marker = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            marker = ("h", r, grid[r][0])
            break
    if marker is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                marker = ("v", c, vals[0])
                break
    if marker is None:
        return [row[:] for row in grid]

    axis, pos, marker_color = marker
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != marker_color]
    if not cells:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    if axis == "v":
        left, right = min(c for r, c, color in cells), max(c for r, c, color in cells)
        if left > pos:
            shift = pos + 1 - left
            new_edge = right + shift
            line = new_edge + 1
        else:
            shift = pos - 1 - right
            new_edge = left + shift
            line = new_edge - 1

        for r, c, color in cells:
            out[r][c] = bg
        for r, c, color in cells:
            out[r][c + shift] = color
        if 0 <= line < w:
            for r in range(h):
                out[r][line] = 8

    else:
        top, bottom = min(r for r, c, color in cells), max(r for r, c, color in cells)
        if top > pos:
            shift = pos + 1 - top
            new_edge = bottom + shift
            line = new_edge + 1
        else:
